/* Detecta el ancho de pantalla con JS puro — las clases responsivas tipo
   "md:" de Tailwind no se compilan de forma confiable en este entorno,
   así que el layout (sidebar vs. menú móvil) se decide aquí, no con CSS. */
function useIsDesktop() {
  const [isDesktop, setIsDesktop] = useState(typeof window !== "undefined" ? window.innerWidth >= 768 : true);
  useEffect(() => {
    const onResize = () => setIsDesktop(window.innerWidth >= 768);
    window.addEventListener("resize", onResize);
    onResize();
    return () => window.removeEventListener("resize", onResize);
  }, []);
  return isDesktop;
}
/* Los inputs de dinero guardan solo dígitos en el estado (nunca el punto de miles),
   y se muestran formateados — así nunca se pierden ceros como con type="number". */
const onlyDigits = (s) => (s || "").replace(/\D/g, "");
const formatMiles = (s) => { const d = onlyDigits(s); return d ? Number(d).toLocaleString("es-CO") : ""; };

