function CarrierBadge({ name, size = 28 }) {
  const logo = CARRIER_LOGOS[name];
  if (logo) {
    return <img src={logo} alt={name} style={{ width: size, height: size, borderRadius: 8, objectFit: "cover" }} />;
  }
  const initials = name.split(" ").map((w) => w[0]).slice(0, 2).join("").toUpperCase();
  const colors = { "Envía": "#E0602A", "TCC": "#B9790A" };
  return (
    <div style={{ width: size, height: size, borderRadius: 8, background: colors[name] || "#555", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: size * 0.34, fontWeight: 700 }}>
      {initials}
    </div>
  );
}

/* ---------------------------------------------------------
   TRANSPORTADORAS + autodetección por prefijo de guía
--------------------------------------------------------- */
const CARRIERS = ["Interrapidísimo", "Envía", "Coordinadora", "Servientrega", "TCC"];

function detectCarrier(guia) {
  const g = guia.replace(/\s/g, "");
  if (!g) return null;
  if (g.startsWith("2400")) return "Interrapidísimo";
  if (g.startsWith("7")) return "Envía";
  if (g.startsWith("3") || g.startsWith("5")) return "Coordinadora";
  return null;
}
function randomGuia(carrier) {
  const rnd = (n) => Math.floor(Math.random() * n).toString().padStart(6, "0");
  if (carrier === "Interrapidísimo") return "2400" + rnd(100000000).toString().padStart(8, "0").slice(0, 8);
  if (carrier === "Envía") return "7" + rnd(1000000).toString().padStart(7, "0");
  if (carrier === "Coordinadora" || carrier === "Servientrega") return "3" + rnd(1000000).toString().padStart(7, "0");
  return "55" + rnd(1000000).toString().padStart(6, "0");
}

