const CIUDADES_ESPECIALES = ["Bucaramanga", "Cúcuta", "Pasto"];

function recommendCarrier(ciudad) {
  if (!ciudad) return null;
  if (ciudad.t === "pueblo") return "Interrapidísimo";
  if (CIUDADES_ESPECIALES.includes(ciudad.n)) return "Servientrega";
  if (ciudad.costa || ciudad.n === "Bogotá") return "Coordinadora";
  return "Interrapidísimo";
}

