function randomPhone() { return "3" + Math.floor(Math.random() * 100000000).toString().padStart(9, "0"); }

/* Genera las órdenes (envíos) a partir de los conteos de cada producto */
function buildOrders(products) {
  let orders = [];
  let n = 0;
  products.forEach((p) => {
    const push = (status) => {
      const carrier = CARRIERS[n % CARRIERS.length];
      const loc = CITY_POOL[n % CITY_POOL.length];
      orders.push({
        nombre: CLIENT_NAMES[n % CLIENT_NAMES.length],
        telefono: randomPhone(),
        ciudad: loc.ciudad,
        departamento: loc.departamento,
        transportadora: carrier,
        guia: randomGuia(carrier),
        status,
        producto: p.nombre,
        valor: p.precio,
      });
      n++;
    };
    for (let i = 0; i < p.entregados; i++) push("entregado");
    for (let i = 0; i < p.devueltos; i++) push("devuelto");
    for (let i = 0; i < p.pendientes; i++) push(i % 9 === 0 ? "novedad" : "viajando");
  });
  return orders;
}

function buildConversation(s) {
  const base = [{ auto: true, time: "8:02 a.m.", text: `Hola ${s.nombre.split(" ")[0]}, tu pedido ${s.guia} fue despachado por ${s.transportadora} 📦` }];
  if (s.status === "viajando" || s.status === "entregado" || s.status === "novedad") {
    base.push({ auto: true, time: "11:40 a.m.", text: `Tu pedido ${s.guia} ya llegó a ${s.ciudad} y va en camino hacia tu dirección 🚚` });
  }
  if (s.status === "novedad" && s.novedadTipo === "guia_duplicada") {
    base.push({ auto: true, time: "1:05 p.m.", text: `⚠️ Novedad con tu pedido ${s.guia}: la transportadora reporta guía duplicada. Paquete en recaudo · Ciudad: ${s.ciudad}. Estamos esperando que el vendedor autorice cómo proceder.` });
    return base;
  }
  if (s.status === "novedad") {
    base.push({ auto: true, time: "2:15 p.m.", text: `No pudimos entregar tu pedido ${s.guia}: no había nadie en la dirección. Responde este mensaje para reprogramar la entrega hoy mismo ⚠️` });
    base.push({ auto: false, time: "2:19 p.m.", text: "Sí hay alguien, por favor reprogramen para la tarde" });
    base.push({ auto: true, time: "2:20 p.m.", text: "Perfecto, reprogramamos tu entrega para hoy entre 3 y 6 p.m. ✅" });
  }
  if (s.status === "entregado") {
    base.push({ auto: true, time: "4:32 p.m.", text: `Tu pedido ${s.guia} fue entregado. ¡Gracias por tu compra! 🎉` });
  }
  if (s.status === "devuelto") {
    base.push({ auto: true, time: "3:10 p.m.", text: `Tu pedido ${s.guia} fue devuelto a la bodega del vendedor tras varios intentos de entrega.` });
  }
  return base;
}

