/* ---------------------------------------------------------
   LOGO / TOGGLE
--------------------------------------------------------- */
function LogoMark({ T, size = 1 }) {
  return (
    <div style={{ lineHeight: 0.85 }}>
      <div className="f-display" style={{ fontSize: 26 * size, color: T.logo, letterSpacing: -1 }}>PRO</div>
      <div className="f-serif italic" style={{ fontSize: 10 * size, color: T.textMuted, letterSpacing: 3, marginTop: 4 }}>SIN LÍMITES</div>
    </div>
  );
}
function ThemeToggle({ isDark, setIsDark, T }) {
  return (
    <button onClick={() => setIsDark(!isDark)} className="w-9 h-9 rounded-full flex items-center justify-center shrink-0"
      style={{ background: T.panelAlt, color: T.textMuted, border: `1px solid ${T.line}` }} title={isDark ? "Modo día" : "Modo noche"}>
      {isDark ? <Sun size={15} /> : <Moon size={15} />}
    </button>
  );
}

