function Login({ onEnter, onGoRegister, onBack, isDark, setIsDark, T }) {
  const [showPw, setShowPw] = useState(false);
  const [correo, setCorreo] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const entrar = async () => {
    setError("");
    if (!correo.trim() || !password) { setError("Ingresa tu correo y contraseña."); return; }
    setLoading(true);
    try {
      const res = await window.storage.get(`account:${correo.trim().toLowerCase()}`);
      if (!res) { setError("No existe una cuenta con este correo. Regístrate primero, o usa la cuenta demo de abajo."); setLoading(false); return; }
      const cuenta = JSON.parse(res.value);
      if (cuenta.password !== password) { setError("Contraseña incorrecta."); setLoading(false); return; }
      setLoading(false);
      onEnter(cuenta);
    } catch (e) {
      setError("No existe una cuenta con este correo. Regístrate primero, o usa la cuenta demo de abajo.");
      setLoading(false);
    }
  };

  const entrarDemo = async () => {
    setError(""); setLoading(true);
    const demo = { nombre: "Cuenta demo", negocio: "PRO Demo", correo: "demo@pro.com", telefono: "", password: "demo1234" };
    try {
      const key = `account:${demo.correo}`;
      let existente = null;
      try { existente = await window.storage.get(key); } catch (e) { existente = null; }
      if (!existente) await window.storage.set(key, JSON.stringify(demo));
      setLoading(false);
      onEnter(demo);
    } catch (e) {
      // Si el almacenamiento falla por completo, igual dejamos entrar en modo demo
      setLoading(false);
      onEnter(demo);
    }
  };

  return (
    <div className="f-body min-h-screen w-full flex items-center justify-center p-6 relative overflow-hidden" style={{ background: "linear-gradient(180deg, #EAD9A8 0%, #C7D89E 35%, #6B9E5C 70%, #2F5A34 100%)" }}>
      {/* Colinas dibujadas en SVG — evita usar una foto real de terceros */}
      <svg className="absolute inset-0 w-full h-full" viewBox="0 0 400 700" preserveAspectRatio="xMidYMid slice">
        <path d="M0 420 Q100 380 200 410 T400 400 V700 H0 Z" fill="#4A7A44" opacity="0.85" />
        <path d="M0 480 Q120 440 220 470 T400 460 V700 H0 Z" fill="#3D6838" opacity="0.9" />
        <path d="M0 550 Q140 510 260 540 T400 530 V700 H0 Z" fill="#2C4F2A" />
      </svg>

      <div className="absolute top-5 left-5 z-10">
        <button onClick={onBack} className="flex items-center gap-1 text-xs font-medium" style={{ color: "#fff" }}><ChevronRight size={14} style={{ transform: "rotate(180deg)" }} /> Volver</button>
      </div>
      <div className="absolute top-5 right-5 z-10"><ThemeToggle isDark={isDark} setIsDark={setIsDark} T={T} /></div>

      <div className="w-full max-w-sm relative z-10">
        <div
          className="rounded-3xl p-6"
          style={{
            background: "rgba(20, 30, 22, 0.35)",
            backdropFilter: "blur(18px)",
            WebkitBackdropFilter: "blur(18px)",
            border: "1px solid rgba(255,255,255,0.25)",
            boxShadow: "0 20px 50px rgba(0,0,0,0.25)",
          }}
        >
          <h1 className="f-display text-2xl" style={{ color: "#fff" }}>Login</h1>
          <p className="text-sm mt-1" style={{ color: "rgba(255,255,255,0.75)" }}>Bienvenido de nuevo, inicia sesión en tu cuenta</p>
          <div className="mt-6 space-y-3">
            <div className="relative">
              <input value={correo} onChange={(e) => setCorreo(e.target.value)} onKeyDown={(e) => e.key === "Enter" && entrar()} type="email" placeholder="Correo" className="w-full px-4 py-3 rounded-xl text-sm outline-none pr-10" style={{ background: "rgba(255,255,255,0.08)", border: "1px solid rgba(255,255,255,0.35)", color: "#fff" }} />
              <User size={16} className="absolute right-3.5 top-3.5" style={{ color: "rgba(255,255,255,0.6)" }} />
            </div>
            <div className="relative">
              <input value={password} onChange={(e) => setPassword(e.target.value)} onKeyDown={(e) => e.key === "Enter" && entrar()} type={showPw ? "text" : "password"} placeholder="Contraseña" className="w-full px-4 py-3 rounded-xl text-sm outline-none pr-10" style={{ background: "rgba(255,255,255,0.08)", border: "1px solid rgba(255,255,255,0.35)", color: "#fff" }} />
              <button onClick={() => setShowPw(!showPw)} className="absolute right-3.5 top-3.5" style={{ color: "rgba(255,255,255,0.6)" }}>
                {showPw ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            </div>
            {error && <p className="text-xs" style={{ color: "#FFB4A8" }}>{error}</p>}
            <label className="flex items-center gap-2 text-xs pt-1 cursor-pointer" style={{ color: "rgba(255,255,255,0.8)" }}>
              <span className="w-4 h-4 rounded flex items-center justify-center" style={{ background: "linear-gradient(135deg, #8CE28C, #2F5A34)" }}><CheckCheck size={11} color="#fff" /></span>
              Recordarme
            </label>
            <button onClick={entrar} disabled={loading} className="w-full py-3 rounded-xl text-sm font-semibold mt-1 flex items-center justify-center gap-2" style={{ background: "linear-gradient(90deg, #8CE28C, #2F8F4A)", color: "#0B2412" }}>
              {loading ? <Loader2 size={15} style={{ animation: "spin 1s linear infinite" }} /> : null} {loading ? "Entrando…" : "Login"}
            </button>
            <p className="text-center text-xs" style={{ color: "rgba(255,255,255,0.75)" }}>
              ¿No tienes cuenta? <button onClick={onGoRegister} className="font-semibold" style={{ color: "#fff" }}>Regístrate</button>
            </p>

            <div className="flex items-center gap-3 pt-1">
              <div className="flex-1 h-px" style={{ background: "rgba(255,255,255,0.25)" }} />
              <span className="text-[11px]" style={{ color: "rgba(255,255,255,0.6)" }}>o</span>
              <div className="flex-1 h-px" style={{ background: "rgba(255,255,255,0.25)" }} />
            </div>
            <button onClick={entrarDemo} disabled={loading} className="w-full py-2.5 rounded-xl text-sm font-medium" style={{ background: "rgba(255,255,255,0.1)", border: "1px solid rgba(255,255,255,0.3)", color: "#fff" }}>
              Entrar con cuenta demo
            </button>
          </div>
          <p className="text-center text-[11px] mt-4" style={{ color: "rgba(255,255,255,0.5)" }}>Creado con <span className="font-semibold">PRO SIN LÍMITES</span></p>
        </div>
      </div>
    </div>
  );
}

function Register({ onEnter, onGoLogin, onBack, isDark, setIsDark, T }) {
  const [showPw, setShowPw] = useState(false);
  const [nombre, setNombre] = useState("");
  const [negocio, setNegocio] = useState("");
  const [correo, setCorreo] = useState("");
  const [telefono, setTelefono] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const inputStyle = { background: T.bg, border: `1px solid ${T.line}`, color: T.text };

  const crearCuenta = async () => {
    setError("");
    if (!nombre.trim() || !correo.trim() || !password) { setError("Completa al menos nombre, correo y contraseña."); return; }
    if (password.length < 4) { setError("La contraseña debe tener al menos 4 caracteres."); return; }
    setLoading(true);
    const key = `account:${correo.trim().toLowerCase()}`;
    try {
      const existente = await window.storage.get(key);
      if (existente) { setError("Ya existe una cuenta con este correo. Inicia sesión."); setLoading(false); return; }
    } catch (e) {
      // no existe la llave -> puede continuar con el registro
    }
    const cuenta = { nombre: nombre.trim(), negocio: negocio.trim(), correo: correo.trim().toLowerCase(), telefono: telefono.trim(), password };
    try {
      const ok = await window.storage.set(key, JSON.stringify(cuenta));
      setLoading(false);
      if (!ok) { setError("No se pudo guardar la cuenta, intenta de nuevo."); return; }
      onEnter(cuenta);
    } catch (e) {
      setLoading(false);
      setError("No se pudo guardar la cuenta, intenta de nuevo.");
    }
  };

  return (
    <div className="f-body min-h-screen w-full flex items-center justify-center p-6 relative" style={{ background: T.bg }}>
      <div className="absolute top-5 left-5">
        <button onClick={onBack} className="flex items-center gap-1 text-xs" style={{ color: T.textMuted }}><ChevronRight size={14} style={{ transform: "rotate(180deg)" }} /> Volver</button>
      </div>
      <div className="absolute top-5 right-5"><ThemeToggle isDark={isDark} setIsDark={setIsDark} T={T} /></div>
      <div className="w-full max-w-sm">
        <div className="flex justify-center mb-8"><LogoMark T={T} size={1.3} /></div>
        <div className="rounded-2xl p-6" style={{ background: T.panel, border: `1px solid ${T.line}` }}>
          <h1 className="text-lg font-semibold text-center" style={{ color: T.text }}>Crea tu cuenta</h1>
          <p className="text-sm text-center mt-1" style={{ color: T.textMuted }}>Empieza a rastrear tus envíos hoy mismo</p>

          <button title="Demo visual — el inicio de sesión con Google real requiere conectar OAuth fuera de este prototipo" className="w-full mt-5 py-2.5 rounded-lg text-sm font-medium flex items-center justify-center gap-2 opacity-60 cursor-not-allowed" style={{ background: T.bg, border: `1px solid ${T.line}`, color: T.text }}>
            <GoogleIcon /> Continuar con Google
          </button>

          <div className="flex items-center gap-3 my-4">
            <div className="flex-1 h-px" style={{ background: T.line }} />
            <span className="text-xs" style={{ color: T.textMuted }}>o con tu correo</span>
            <div className="flex-1 h-px" style={{ background: T.line }} />
          </div>

          <div className="space-y-3">
            <input value={nombre} onChange={(e) => setNombre(e.target.value)} placeholder="Nombre completo" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
            <input value={negocio} onChange={(e) => setNegocio(e.target.value)} placeholder="Nombre de tu ecommerce" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
            <input value={correo} onChange={(e) => setCorreo(e.target.value)} type="email" placeholder="Correo" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
            <input value={telefono} onChange={(e) => setTelefono(e.target.value)} placeholder="Teléfono" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
            <div className="relative">
              <input value={password} onChange={(e) => setPassword(e.target.value)} type={showPw ? "text" : "password"} placeholder="Crea una contraseña" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none pr-10" style={inputStyle} />
              <button onClick={() => setShowPw(!showPw)} className="absolute right-3 top-2.5" style={{ color: T.textMuted }}>
                {showPw ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            </div>
            {error && <p className="text-xs" style={{ color: T.danger }}>{error}</p>}
            <button onClick={crearCuenta} disabled={loading} className="w-full py-2.5 rounded-lg text-sm font-semibold mt-1 flex items-center justify-center gap-2" style={{ background: T.route, color: "#fff" }}>
              {loading ? <Loader2 size={15} style={{ animation: "spin 1s linear infinite" }} /> : null} {loading ? "Creando cuenta…" : "Crear cuenta"}
            </button>
          </div>

          <p className="text-center text-xs mt-4" style={{ color: T.textMuted }}>
            ¿Ya tienes cuenta? <button onClick={onGoLogin} className="hover:underline font-medium" style={{ color: T.route }}>Inicia sesión</button>
          </p>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   BANNER DE META
--------------------------------------------------------- */
function GoalBanner({ T, shipments }) {
  const entregados = shipments.filter((s) => s.status === "entregado").length;
  const devueltos = shipments.filter((s) => s.status === "devuelto").length;
  const denom = entregados + devueltos;
  const efectividad = denom > 0 ? (entregados / denom) * 100 : 0;
  const meta = 96;
  const ok = efectividad >= meta;
  return (
    <div className="rounded-2xl p-4 mb-6" style={{ background: T.panel, border: `1px solid ${T.line}`, boxShadow: T.shadow }}>
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2.5">
          <div className="w-7 h-7 rounded-full flex items-center justify-center shrink-0" style={{ background: `${T.route}1A` }}>
            <Target size={14} style={{ color: T.route }} />
          </div>
          <p className="text-sm font-semibold" style={{ color: T.text }}>Meta: {meta}% de efectividad logística</p>
        </div>
        <span className="text-sm font-semibold" style={{ color: ok ? T.ok : T.warn }}>{efectividad.toFixed(1)}%</span>
      </div>
      <div className="w-full h-2 rounded-full overflow-hidden" style={{ background: T.panelAlt }}>
        <div className="h-full rounded-full" style={{ width: `${Math.min(efectividad, 100)}%`, background: ok ? T.ok : T.warn }} />
      </div>
      <p className="text-xs mt-2" style={{ color: T.textMuted }}>
        {ok ? "¡Vas por encima de la meta! Sigue así." : `Te faltan ${(meta - efectividad).toFixed(1)} puntos para llegar a la meta.`}
      </p>
    </div>
  );
}

