/* ---------------------------------------------------------
   VISTA: Mapa esquemático de zonas calientes de devolución
--------------------------------------------------------- */
function effectivenessFor(cityName) {
  const known = HEAT_CITIES.find((c) => c.n === cityName);
  const rate = known ? known.rate : 6; // tasa típica cuando no hay dato puntual
  const eff = 96 - rate * 0.3;
  return Math.max(90, Math.min(96, eff));
}

/* ---------------------------------------------------------
   VISTA: Recomendador de transportadora
--------------------------------------------------------- */
/* Tarifas contra entrega dadas por el cliente: base a $50.000 de valor cotizado,
   +$2.000 por cada $50.000 adicionales (lineal: +$1.000 por cada $25.000). */
const CARRIER_COD_BASE = { "Coordinadora": 20200, "Interrapidísimo": 22750, "Servientrega": 23200, "Envía": 19870 };
function codPrice(carrier, valor) {
  const base = CARRIER_COD_BASE[carrier];
  const incremento = ((Number(valor) || 50000) - 50000) / 50000 * 2000;
  return Math.round(base + incremento);
}

function RecommenderView({ T }) {
  const [sub, setSub] = useState("recomendador");
  const [depSel, setDepSel] = useState("");
  const [ciudadSel, setCiudadSel] = useState("");
  const [pago, setPago] = useState("contra_entrega");
  const [valorCotizado, setValorCotizado] = useState("100000");
  const [seleccionada, setSeleccionada] = useState(null);

  const depObj = COLOMBIA.find((d) => d.dep === depSel);
  const ciudadObj = depObj?.ciudades.find((c) => c.n === ciudadSel);
  const carrier = ciudadObj ? recommendCarrier(ciudadObj) : null;
  const eff = ciudadSel ? effectivenessFor(ciudadSel) : null;
  const inputStyle = { background: T.panel, border: `1px solid ${T.line}`, color: T.text };

  const cotizacion = Object.keys(CARRIER_COD_BASE)
    .map((c) => ({ carrier: c, precio: codPrice(c, valorCotizado) }))
    .sort((a, b) => a.precio - b.precio);

  return (
    <div className="max-w-2xl mx-auto">
      <div className="flex gap-2 mb-4">
        <button onClick={() => setSub("recomendador")} className="flex-1 py-2 rounded-lg text-xs font-medium" style={{ background: sub === "recomendador" ? T.route : "transparent", color: sub === "recomendador" ? "#fff" : T.textMuted, border: `1px solid ${sub === "recomendador" ? T.route : T.line}` }}>Recomendador</button>
        <button onClick={() => setSub("cotizado")} className="flex-1 py-2 rounded-lg text-xs font-medium" style={{ background: sub === "cotizado" ? T.route : "transparent", color: sub === "cotizado" ? "#fff" : T.textMuted, border: `1px solid ${sub === "cotizado" ? T.route : T.line}` }}>Cotizador</button>
      </div>

      <p className="text-sm mb-4" style={{ color: T.textMuted }}>
        {sub === "recomendador" ? "Selecciona el destino del pedido y te decimos qué transportadora conviene más." : "Cotiza el precio de envío con cada transportadora según el valor del pedido."}
      </p>
      <div className="grid grid-cols-2 gap-2 mb-4">
        <select value={depSel} onChange={(e) => { setDepSel(e.target.value); setCiudadSel(""); }} className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle}>
          <option value="">Departamento</option>
          {COLOMBIA.map((d) => <option key={d.dep} value={d.dep}>{d.dep}</option>)}
        </select>
        <select value={ciudadSel} onChange={(e) => setCiudadSel(e.target.value)} className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} disabled={!depSel}>
          <option value="">Ciudad / municipio</option>
          {depObj?.ciudades.map((c) => <option key={c.n} value={c.n}>{c.n}{c.t === "pueblo" ? " (pueblo)" : ""}</option>)}
        </select>
      </div>

      {sub === "recomendador" ? (
        carrier && (
          <div className="rounded-2xl p-4" style={{ background: T.panel, border: `1px solid ${T.line}` }}>
            <div className="flex items-center gap-3 mb-3">
              <CarrierBadge name={carrier} size={40} />
              <div>
                <p className="text-sm font-semibold" style={{ color: T.text }}>{carrier}</p>
                <p className="text-xs" style={{ color: T.textMuted }}>Transportadora recomendada para {ciudadSel}</p>
              </div>
            </div>
            <div className="w-full h-2.5 rounded-full overflow-hidden mb-2" style={{ background: T.panelAlt }}>
              <div className="h-full rounded-full" style={{ width: `${eff}%`, background: T.ok }} />
            </div>
            <p className="text-xs font-medium" style={{ color: T.ok }}>✓ {eff.toFixed(1)}% de efectividad de entrega esperada — transportadora recomendada y apta para esta ciudad</p>
          </div>
        )
      ) : (
        <div>
          <div className="flex gap-2 mb-3">
            <button onClick={() => setPago("contra_entrega")} className="flex-1 py-2 rounded-lg text-xs font-medium" style={{ background: pago === "contra_entrega" ? T.route : "transparent", color: pago === "contra_entrega" ? "#fff" : T.textMuted, border: `1px solid ${pago === "contra_entrega" ? T.route : T.line}` }}>Contra entrega</button>
            <button onClick={() => setPago("anticipado")} className="flex-1 py-2 rounded-lg text-xs font-medium" style={{ background: pago === "anticipado" ? T.route : "transparent", color: pago === "anticipado" ? "#fff" : T.textMuted, border: `1px solid ${pago === "anticipado" ? T.route : T.line}` }}>Anticipado</button>
          </div>
          <label className="text-xs" style={{ color: T.textMuted }}>Valor cotizado del pedido</label>
          <input inputMode="numeric" value={formatMiles(valorCotizado)} onChange={(e) => setValorCotizado(onlyDigits(e.target.value))} className="w-full mt-1 mb-4 px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />

          <div className="space-y-2">
            {pago === "contra_entrega" ? (
              cotizacion.map((c) => (
                <button
                  key={c.carrier}
                  onClick={() => setSeleccionada(c.carrier)}
                  className="w-full flex items-center justify-between p-3 rounded-xl"
                  style={{ background: T.panel, border: `2px solid ${seleccionada === c.carrier ? T.route : T.line}` }}
                >
                  <div className="flex items-center gap-2.5">
                    <CarrierBadge name={c.carrier} size={30} />
                    <div className="text-left">
                      <p className="text-sm font-medium" style={{ color: T.text }}>{c.carrier}</p>
                      {ciudadObj && recommendCarrier(ciudadObj) === c.carrier && (
                        <p className="text-[11px]" style={{ color: T.ok }}>★ recomendada para {ciudadSel}</p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-semibold" style={{ color: T.text }}>{money(c.precio)}</p>
                    {seleccionada === c.carrier && <CheckCircle2 size={16} style={{ color: T.route }} />}
                  </div>
                </button>
              ))
            ) : (
              Object.keys(CARRIER_COD_BASE).map((c) => (
                <div key={c} className="w-full flex items-center justify-between p-3 rounded-xl" style={{ background: T.panel, border: `1px solid ${T.line}` }}>
                  <div className="flex items-center gap-2.5">
                    <CarrierBadge name={c} size={30} />
                    <p className="text-sm font-medium" style={{ color: T.text }}>{c}</p>
                  </div>
                  <p className="text-xs" style={{ color: T.textMuted }}>Consulta tarifa anticipada</p>
                </div>
              ))
            )}
          </div>
          {pago === "anticipado" && (
            <p className="text-[11px] mt-2" style={{ color: T.textMuted }}>Aún no tengo tarifas de envío anticipado — solo me diste las de contra entrega. Avísame los precios y las agrego.</p>
          )}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------
   VISTA: Calculadora de rentabilidad
--------------------------------------------------------- */
function CalculatorView({ T }) {
  const [precioVenta, setPrecioVenta] = useState("300000");
  const [costoProducto, setCostoProducto] = useState("120000");
  const [costoEnvio, setCostoEnvio] = useState("15000");
  const [costoAnuncio, setCostoAnuncio] = useState("25000");
  const inputStyle = { background: T.panel, border: `1px solid ${T.line}`, color: T.text };

  const pv = Number(precioVenta) || 0;
  const cp = Number(costoProducto) || 0;
  const ce = Number(costoEnvio) || 0;
  const ca = Number(costoAnuncio) || 0;
  const ganancia = pv - cp - ce - ca;
  const margen = pv > 0 ? (ganancia / pv) * 100 : 0;

  const Field = ({ label, value, setValue }) => (
    <div>
      <label className="text-xs" style={{ color: T.textMuted }}>{label}</label>
      <input inputMode="numeric" value={formatMiles(value)} onChange={(e) => setValue(onlyDigits(e.target.value))} className="w-full mt-1 px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
    </div>
  );

  return (
    <div className="max-w-2xl mx-auto">
      <p className="text-sm mb-4" style={{ color: T.textMuted }}>Calcula tu ganancia real después de anuncio, envío y costo de producto.</p>
      <div className="space-y-3">
        <Field label="Precio de venta" value={precioVenta} setValue={setPrecioVenta} />
        <Field label="Costo del producto" value={costoProducto} setValue={setCostoProducto} />
        <Field label="Costo de envío" value={costoEnvio} setValue={setCostoEnvio} />
        <Field label="Costo de anuncio (ads)" value={costoAnuncio} setValue={setCostoAnuncio} />
      </div>

      <div className="rounded-2xl p-4 mt-5" style={{ background: T.panel, border: `1px solid ${T.line}` }}>
        <div className="flex items-center justify-between">
          <p className="text-sm" style={{ color: T.textMuted }}>Ganancia neta por entrega</p>
          <p className="text-lg font-semibold" style={{ color: ganancia >= 0 ? T.ok : T.danger }}>{money(ganancia)}</p>
        </div>
        <div className="flex items-center justify-between mt-2">
          <p className="text-xs" style={{ color: T.textMuted }}>Margen</p>
          <p className="text-xs font-medium" style={{ color: ganancia >= 0 ? T.ok : T.danger }}>{margen.toFixed(1)}%</p>
        </div>
        <div className="w-full h-2 rounded-full overflow-hidden mt-3" style={{ background: T.panelAlt }}>
          <div className="h-full rounded-full" style={{ width: `${Math.max(Math.min(margen, 100), 0)}%`, background: ganancia >= 0 ? T.ok : T.danger }} />
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   PANEL: WhatsApp automático
--------------------------------------------------------- */
function WhatsAppPanel({ s, onClose, onResolve, onUpdate }) {
  const conv = buildConversation(s);
  const pendienteDecision = s.status === "novedad" && s.novedadTipo === "guia_duplicada";
  const [accion, setAccion] = useState(null); // null | "precio" | "direccion"
  const [nuevoPrecio, setNuevoPrecio] = useState(String(s.valor || ""));
  const [nuevaDireccion, setNuevaDireccion] = useState(s.direccion || "");
  const [extraMsgs, setExtraMsgs] = useState([]);

  const confirmarPrecio = () => {
    const v = Number(nuevoPrecio) || 0;
    onUpdate(s.guia, { valor: v });
    setExtraMsgs((m) => [...m, { auto: false, time: "ahora", text: `Cambiar precio del recaudo a $${v.toLocaleString("es-CO")}` }, { auto: true, time: "ahora", text: "Valor del recaudo actualizado ✅" }]);
    setAccion(null);
  };
  const confirmarDireccion = () => {
    if (!nuevaDireccion.trim()) return;
    onUpdate(s.guia, { direccion: nuevaDireccion.trim() });
    setExtraMsgs((m) => [...m, { auto: false, time: "ahora", text: `Nueva dirección de entrega: ${nuevaDireccion.trim()}` }, { auto: true, time: "ahora", text: "Dirección actualizada ✅" }]);
    setAccion(null);
  };

  return (
    <div className="fixed inset-0 z-30 flex justify-end" style={{ background: "#000000B0" }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-sm h-full flex flex-col" style={{ background: WA.waBg }}>
        <div className="flex items-center gap-3 px-4 py-3" style={{ background: WA.waIn }}>
          <div className="w-9 h-9 rounded-full flex items-center justify-center text-sm font-semibold" style={{ background: "#3D5FDB", color: "#fff" }}>
            {s.nombre.split(" ").map((p) => p[0]).slice(0, 2).join("")}
          </div>
          <div className="flex-1">
            <p className="text-sm font-medium" style={{ color: "#fff" }}>{s.nombre}</p>
            <p className="text-xs" style={{ color: "#8A9A9E" }}>Línea automática · {s.telefono}</p>
          </div>
          <button onClick={onClose} style={{ color: "#fff" }}><X size={18} /></button>
        </div>
        <div className="flex-1 overflow-y-auto px-3 py-4 space-y-2">
          {conv.map((m, i) => (
            <div key={i} className="flex" style={{ justifyContent: m.auto ? "flex-start" : "flex-end" }}>
              <div className="max-w-[80%] rounded-xl px-3 py-2 text-sm" style={{ background: m.auto ? WA.waIn : WA.waBubble, color: "#E9EDEF" }}>
                <p>{m.text}</p>
                <p className="text-[10px] mt-1 flex items-center gap-1 justify-end" style={{ color: "#8A9A9E" }}>{m.time} {!m.auto && <CheckCheck size={12} style={{ color: "#5C86FF" }} />}</p>
              </div>
            </div>
          ))}

          {extraMsgs.map((m, i) => (
            <div key={`x${i}`} className="flex" style={{ justifyContent: m.auto ? "flex-start" : "flex-end" }}>
              <div className="max-w-[80%] rounded-xl px-3 py-2 text-sm" style={{ background: m.auto ? WA.waIn : WA.waBubble, color: "#E9EDEF" }}>
                <p>{m.text}</p>
                <p className="text-[10px] mt-1 flex items-center gap-1 justify-end" style={{ color: "#8A9A9E" }}>{m.time} {!m.auto && <CheckCheck size={12} style={{ color: "#5C86FF" }} />}</p>
              </div>
            </div>
          ))}

          {pendienteDecision && (
            <div className="rounded-xl p-3 mt-2" style={{ background: WA.waIn }}>
              <p className="text-xs mb-2.5" style={{ color: "#E9EDEF" }}>
                📦 Guía {s.guia} · Paquete en recaudo · Ciudad: {s.ciudad}. La transportadora reporta guía duplicada — como vendedor, decide cómo proceder:
              </p>
              <div className="grid grid-cols-2 gap-2">
                <button onClick={() => onResolve(s, "entregado")} className="py-2 rounded-lg text-xs font-semibold" style={{ background: "#25D366", color: "#0B141A" }}>
                  Autorizar entrega
                </button>
                <button onClick={() => onResolve(s, "devuelto")} className="py-2 rounded-lg text-xs font-semibold" style={{ background: "#F0563D", color: "#fff" }}>
                  Devolución total
                </button>
                <button onClick={() => setAccion(accion === "precio" ? null : "precio")} className="py-2 rounded-lg text-xs font-semibold" style={{ background: accion === "precio" ? "#5C86FF" : "#0B141A", color: "#fff", border: "1px solid #5C86FF" }}>
                  Cambiar precio del recaudo
                </button>
                <button onClick={() => setAccion(accion === "direccion" ? null : "direccion")} className="py-2 rounded-lg text-xs font-semibold" style={{ background: accion === "direccion" ? "#5C86FF" : "#0B141A", color: "#fff", border: "1px solid #5C86FF" }}>
                  Nueva dirección de entrega
                </button>
              </div>

              {accion === "precio" && (
                <div className="flex gap-2 mt-2.5">
                  <input inputMode="numeric" value={formatMiles(nuevoPrecio)} onChange={(e) => setNuevoPrecio(onlyDigits(e.target.value))} placeholder="Nuevo valor del recaudo" className="flex-1 px-3 py-2 rounded-lg text-sm outline-none" style={{ background: "#0B141A", border: "1px solid #2A3942", color: "#E9EDEF" }} />
                  <button onClick={confirmarPrecio} className="px-3 py-2 rounded-lg text-xs font-semibold" style={{ background: "#25D366", color: "#0B141A" }}>Confirmar</button>
                </div>
              )}
              {accion === "direccion" && (
                <div className="flex gap-2 mt-2.5">
                  <input value={nuevaDireccion} onChange={(e) => setNuevaDireccion(e.target.value)} placeholder="Nueva dirección de entrega" className="flex-1 px-3 py-2 rounded-lg text-sm outline-none" style={{ background: "#0B141A", border: "1px solid #2A3942", color: "#E9EDEF" }} />
                  <button onClick={confirmarDireccion} className="px-3 py-2 rounded-lg text-xs font-semibold" style={{ background: "#25D366", color: "#0B141A" }}>Confirmar</button>
                </div>
              )}
            </div>
          )}

          <p className="text-center text-[11px] pt-2" style={{ color: "#5C6B70" }}>Mensajes enviados automáticamente por cambio de estado — sin intervención manual</p>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   PANEL: chat interno con la plataforma
--------------------------------------------------------- */
function SupportChat({ onClose, T }) {
  const [messages, setMessages] = useState([{ from: "soporte", time: "9:05 a.m.", text: "Hola, somos el equipo de soporte PRO. Cuéntanos si tienes una novedad con algún envío." }]);
  const [text, setText] = useState("");
  const send = () => {
    if (!text.trim()) return;
    setMessages((m) => [...m, { from: "yo", time: "ahora", text }]);
    setText("");
    setTimeout(() => setMessages((m) => [...m, { from: "soporte", time: "ahora", text: "Recibido, ya estamos revisando la novedad de esa guía y te contamos en breve." }]), 1200);
  };
  return (
    <div className="fixed inset-0 z-30 flex justify-end" style={{ background: "#000000B0" }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-sm h-full flex flex-col" style={{ background: T.bg }}>
        <div className="flex items-center gap-3 px-4 py-3" style={{ background: T.panel, borderBottom: `1px solid ${T.line}` }}>
          <div className="w-9 h-9 rounded-full flex items-center justify-center" style={{ background: `${T.route}1A`, color: T.route }}><LifeBuoy size={16} /></div>
          <div className="flex-1">
            <p className="text-sm font-medium" style={{ color: T.text }}>Chat con la plataforma</p>
            <p className="text-xs" style={{ color: T.textMuted }}>Soporte para novedades y ajustes</p>
          </div>
          <button onClick={onClose} style={{ color: T.textMuted }}><X size={18} /></button>
        </div>
        <div className="flex-1 overflow-y-auto px-3 py-4 space-y-2">
          {messages.map((m, i) => (
            <div key={i} className="flex" style={{ justifyContent: m.from === "soporte" ? "flex-start" : "flex-end" }}>
              <div className="max-w-[80%] rounded-xl px-3 py-2 text-sm" style={{ background: m.from === "soporte" ? T.panelAlt : T.route, color: m.from === "soporte" ? T.text : "#fff" }}>
                <p>{m.text}</p>
                <p className="text-[10px] mt-1 opacity-70">{m.time}</p>
              </div>
            </div>
          ))}
        </div>
        <div className="flex items-center gap-2 p-3" style={{ borderTop: `1px solid ${T.line}` }}>
          <input value={text} onChange={(e) => setText(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()} placeholder="Escribe tu mensaje…" className="flex-1 px-3 py-2 rounded-lg text-sm outline-none" style={{ background: T.panel, border: `1px solid ${T.line}`, color: T.text }} />
          <button onClick={send} className="w-9 h-9 rounded-full flex items-center justify-center shrink-0" style={{ background: T.route, color: "#fff" }}><Send size={15} /></button>
        </div>
      </div>
    </div>
  );
}

