function WithdrawModal({ onClose, disponible, bankAccount, onSaveBank, onWithdraw, T }) {
  const [titular, setTitular] = useState(bankAccount?.titular || "");
  const [entidad, setEntidad] = useState(bankAccount?.entidad || "");
  const [cuenta, setCuenta] = useState(bankAccount?.cuenta || "");
  const [tipo, setTipo] = useState(bankAccount?.tipo || "ahorros");
  const [monto, setMonto] = useState(String(disponible));
  const [done, setDone] = useState(false);
  const inputStyle = { background: T.bg, border: `1px solid ${T.line}`, color: T.text };

  const esRapida = (e) => e === "Nequi" || e === "Bancolombia";
  const tiempoTexto = (e) => (esRapida(e) ? "máximo 24 horas" : "entre 24 y 48 horas");

  const guardarCuenta = () => {
    if (!titular.trim() || !entidad || !cuenta.trim()) return;
    onSaveBank({ titular: titular.trim(), entidad, cuenta: cuenta.trim(), tipo });
  };
  const solicitar = () => {
    const m = Math.min(Number(monto) || 0, disponible);
    if (m <= 0) return;
    onWithdraw(m);
    setDone(true);
  };

  return (
    <div className="fixed inset-0 z-30 flex items-center justify-center p-4" style={{ background: "#000000B0" }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} className="w-full max-w-sm rounded-2xl p-5 max-h-[90vh] overflow-y-auto" style={{ background: T.panel, border: `1px solid ${T.line}` }}>
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold" style={{ color: T.text }}>Retirar recaudo</h2>
          <button onClick={onClose} style={{ color: T.textMuted }}><X size={18} /></button>
        </div>

        {done ? (
          <div className="py-6 flex flex-col items-center gap-2 text-center">
            <CheckCircle2 size={26} style={{ color: T.ok }} />
            <p className="text-sm font-semibold" style={{ color: T.text }}>Retiro solicitado</p>
            <p className="text-xs" style={{ color: T.textMuted }}>
              El dinero será abonado a tu cuenta {bankAccount?.entidad} en {tiempoTexto(bankAccount?.entidad)} luego de la aprobación.
            </p>
            <button onClick={onClose} className="mt-2 px-4 py-2 rounded-lg text-sm font-semibold" style={{ background: T.route, color: "#fff" }}>Cerrar</button>
          </div>
        ) : !bankAccount ? (
          <div className="space-y-3">
            <p className="text-xs" style={{ color: T.textMuted }}>Primero agrega la cuenta a la que quieres que enviemos tu recaudo.</p>
            <input value={titular} onChange={(e) => setTitular(e.target.value)} placeholder="Nombre del titular" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
            <select value={entidad} onChange={(e) => setEntidad(e.target.value)} className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle}>
              <option value="">Cuenta (banco o billetera)</option>
              {BANKS.map((b) => <option key={b} value={b}>{b}</option>)}
            </select>
            <input value={cuenta} onChange={(e) => setCuenta(e.target.value)} placeholder="Número de cuenta" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
            <select value={tipo} onChange={(e) => setTipo(e.target.value)} className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle}>
              <option value="ahorros">Cuenta de ahorros</option>
              <option value="corriente">Cuenta corriente</option>
            </select>
            {entidad && (
              <p className="text-[11px]" style={{ color: T.textMuted }}>
                {esRapida(entidad)
                  ? `Con ${entidad} el abono llega en máximo 24 horas.`
                  : `Con ${entidad || "este banco"} el abono llega entre 24 y 48 horas.`}
              </p>
            )}
            <button onClick={guardarCuenta} className="w-full py-2.5 rounded-lg text-sm font-semibold" style={{ background: T.route, color: "#fff" }}>Guardar cuenta</button>
          </div>
        ) : (
          <div className="space-y-3">
            <div className="rounded-lg p-3 text-xs" style={{ background: T.bg, border: `1px solid ${T.line}`, color: T.textMuted }}>
              {bankAccount.entidad} · Cuenta {bankAccount.tipo === "ahorros" ? "de ahorros" : "corriente"} termina en {bankAccount.cuenta.slice(-4)} · Titular: {bankAccount.titular}
            </div>
            <label className="text-xs" style={{ color: T.textMuted }}>Saldo a retirar (disponible: {money(disponible)})</label>
            <input inputMode="numeric" value={formatMiles(monto)} onChange={(e) => setMonto(onlyDigits(e.target.value))} className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
            <button onClick={solicitar} className="w-full py-2.5 rounded-lg text-sm font-semibold" style={{ background: T.route, color: "#fff" }}>Solicitar retiro</button>
            <p className="text-[11px] text-center" style={{ color: T.textMuted }}>
              {esRapida(bankAccount.entidad)
                ? `Con ${bankAccount.entidad}, el dinero será abonado máximo 24 horas luego de la aprobación.`
                : `Con ${bankAccount.entidad}, el dinero será abonado entre 24 y 48 horas luego de la aprobación.`}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Generador de PDF simple (sin librerías externas) — construye
   un PDF de una página válido a partir de líneas de texto plano.
--------------------------------------------------------- */
function buildGuidePdfBytes(lines) {
  const enc = new TextEncoder();
  // El formato PDF de texto simple no soporta acentos/ñ de forma confiable
  // con la fuente Helvetica estándar, así que se transliteran para evitar
  // caracteres corruptos en el PDF final.
  const translit = (s) =>
    String(s)
      .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
      .replace(/ñ/g, "n").replace(/Ñ/g, "N");
  const escapeStr = (s) => translit(s).replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");

  let content = "BT\n/F1 11 Tf\n50 760 Td\n16 TL\n";
  lines.forEach((line, i) => {
    if (i > 0) content += "T*\n";
    content += `(${escapeStr(line)}) Tj\n`;
  });
  content += "ET";
  const contentBytes = enc.encode(content);

  const chunks = [];
  let offset = 0;
  const push = (str) => { const b = enc.encode(str); chunks.push(b); offset += b.length; };
  const pushBytes = (b) => { chunks.push(b); offset += b.length; };

  push("%PDF-1.4\n");
  const offsets = [0];

  offsets.push(offset); push("1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n");
  offsets.push(offset); push("2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n");
  offsets.push(offset); push("3 0 obj\n<< /Type /Page /Parent 2 0 R /Resources << /Font << /F1 4 0 R >> >> /MediaBox [0 0 612 792] /Contents 5 0 R >>\nendobj\n");
  offsets.push(offset); push("4 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n");
  offsets.push(offset);
  push(`5 0 obj\n<< /Length ${contentBytes.length} >>\nstream\n`);
  pushBytes(contentBytes);
  push("\nendstream\nendobj\n");

  const xrefStart = offset;
  let xref = "xref\n0 6\n0000000000 65535 f \n";
  for (let i = 1; i <= 5; i++) xref += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
  push(xref);
  push(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`);

  const total = chunks.reduce((a, b) => a + b.length, 0);
  const out = new Uint8Array(total);
  let p = 0;
  chunks.forEach((b) => { out.set(b, p); p += b.length; });
  return out;
}

function downloadGuidePdf(guia) {
  const lines = [
    "PRO SIN LIMITES",
    "Guia de envio local",
    `Tipo de pago: ${guia.pago === "contra_entrega" ? "Contra entrega" : "Anticipado"}`,
    "",
    `Guia: ${guia.guia}`,
    `Cliente: ${guia.nombre}`,
    `Telefono: ${guia.telefono}`,
    `Municipio: ${guia.municipio}`,
    `Direccion: ${guia.direccion}`,
    `Recoge: ${guia.operador}`,
    `Valor del pedido: $${Math.round(guia.precio).toLocaleString("es-CO")}`,
    `Costo de envio: $${Math.round(guia.costoEnvio).toLocaleString("es-CO")}`,
    `Recogida: ${guia.fecha} ${guia.hora}`,
    "",
    "Generada y pagada con PRO SIN LIMITES",
  ];
  const bytes = buildGuidePdfBytes(lines);
  const blob = new Blob([bytes], { type: "application/pdf" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `guia-${guia.guia}.pdf`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

