/* ---------------------------------------------------------
   ENVÍOS NACIONALES — genera la guía en el formato real
   de Interrapidísimo o Coordinadora, con el logo PRO en pequeño.
--------------------------------------------------------- */
function BarcodePlaceholder({ seed = "", height = 46, width = "100%" }) {
  let s = 0;
  for (let i = 0; i < seed.length; i++) s += seed.charCodeAt(i) * (i + 7);
  const rand = (i) => {
    const x = Math.sin((i * 12.9898) + s) * 43758.5453;
    return x - Math.floor(x);
  };
  const bars = Array.from({ length: 70 }, (_, i) => {
    const r = rand(i);
    return r > 0.82 ? 3 : r > 0.55 ? 2 : 1;
  });
  return (
    <div className="flex items-stretch gap-[1px]" style={{ height, width }}>
      {bars.map((w, i) => <div key={i} style={{ width: w, background: i % 5 === 4 ? "#fff" : "#000", flexShrink: 0 }} />)}
    </div>
  );
}

/* Placeholder de QR realista (visual únicamente — no codifica datos reales) */
function QRPlaceholder({ seed = "", size = 84 }) {
  const n = 21;
  const cell = size / n;
  let s = 0;
  for (let i = 0; i < seed.length; i++) s += seed.charCodeAt(i) * (i + 3);
  const rand = (r, c) => {
    const x = Math.sin(r * 12.9898 + c * 78.233 + s) * 43758.5453;
    return x - Math.floor(x) > 0.5;
  };
  const corners = [[0, 0], [0, n - 7], [n - 7, 0]];
  const inFinder = (r, c) => corners.find(([fr, fc]) => r >= fr && r < fr + 7 && c >= fc && c < fc + 7);
  const finderOn = (r, c, fr, fc) => {
    const lr = r - fr, lc = c - fc;
    return lr === 0 || lr === 6 || lc === 0 || lc === 6 || (lr >= 2 && lr <= 4 && lc >= 2 && lc <= 4);
  };
  const rects = [];
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      const f = inFinder(r, c);
      const on = f ? finderOn(r, c, f[0], f[1]) : rand(r, c);
      if (on) rects.push(<rect key={`${r}-${c}`} x={c * cell} y={r * cell} width={cell} height={cell} fill="black" />);
    }
  }
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ background: "#fff" }}>
      {rects}
    </svg>
  );
}

