function NationalShippingView({ T }) {
  const [nombre, setNombre] = useState("");
  const [telefono, setTelefono] = useState("");
  const [correo, setCorreo] = useState("");
  const [direccion, setDireccion] = useState("");
  const [depSel, setDepSel] = useState("");
  const [ciudadSel, setCiudadSel] = useState("");
  const [valor, setValor] = useState("");
  const [contenido, setContenido] = useState("");
  const [cantidad, setCantidad] = useState("1");
  const [guideOpen, setGuideOpen] = useState(null);

  const depObj = COLOMBIA.find((x) => x.dep === depSel);
  const inputStyle = { background: T.panel, border: `1px solid ${T.line}`, color: T.text };

  const datosCompletos = nombre.trim() && telefono.trim() && direccion.trim() && ciudadSel && valor;

  const generar = (transportadora) => {
    if (!datosCompletos) return;
    const hoy = new Date();
    const guia = {
      transportadora, nombre: nombre.trim(), telefono: telefono.trim(), correo: correo.trim() || "sin-correo@cliente.com",
      direccion: direccion.trim(), ciudad: ciudadSel, departamento: depSel,
      valor: Number(valor) || 0, contenido: contenido.trim() || "Producto", cantidad: Number(cantidad) || 1,
      guia: randomGuia(transportadora), origenCod: "BOG", destinoCod: "MDE",
      fecha: hoy.toLocaleDateString("es-CO"), fechaHora: hoy.toLocaleDateString("es-CO") + " - " + hoy.toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit" }),
    };
    setGuideOpen(guia);
  };

  return (
    <div className="max-w-2xl mx-auto">
      {/* Banner promocional de transportadora */}
      <div className="rounded-2xl p-5 mb-5 relative overflow-hidden flex items-center justify-between gap-4" style={{ background: "linear-gradient(115deg, #C9202A 0%, #8E1319 100%)" }}>
        <svg className="absolute inset-0 w-full h-full opacity-25" viewBox="0 0 400 110" preserveAspectRatio="xMidYMid slice">
          <path d="M0 90 Q100 60 200 85 T400 65" stroke="#fff" strokeWidth="1" fill="none" />
          <path d="M0 100 Q120 75 240 95 T400 80" stroke="#fff" strokeWidth="1" fill="none" opacity="0.6" />
        </svg>
        <div className="relative z-10">
          <span className="inline-block text-[11px] font-semibold px-2.5 py-1 rounded-full mb-2" style={{ background: "#ffffff25", color: "#fff" }}>🚚 Transportadora recomendada</span>
          <h2 className="f-display text-xl" style={{ color: "#fff" }}>Interrapidísimo</h2>
          <p className="text-xs mt-1" style={{ color: "#FBD5D5" }}>La opción más confiable para pueblos y municipios apartados de Colombia.</p>
        </div>
        <div className="relative z-10 text-right shrink-0">
          <p className="text-2xl font-bold" style={{ color: "#fff" }}>98%</p>
          <p className="text-[11px]" style={{ color: "#FBD5D5" }}>de efectividad</p>
        </div>
      </div>

      <p className="text-sm mb-4" style={{ color: T.textMuted }}>Genera la guía nacional con el mismo formato que usa cada transportadora, lista para descargar.</p>

      <div className="rounded-2xl p-4 space-y-3" style={{ background: T.panel, border: `1px solid ${T.line}` }}>
        <input value={nombre} onChange={(e) => setNombre(e.target.value)} placeholder="Nombre del cliente" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
        <input value={telefono} onChange={(e) => setTelefono(e.target.value)} placeholder="Teléfono" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
        <ClientHistoryCard telefono={telefono} T={T} />
        <input value={correo} onChange={(e) => setCorreo(e.target.value)} type="email" placeholder="Correo electrónico" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
        <div className="grid grid-cols-2 gap-2">
          <select value={depSel} onChange={(e) => { setDepSel(e.target.value); setCiudadSel(""); }} className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle}>
            <option value="">Departamento</option>
            {COLOMBIA.map((d) => <option key={d.dep} value={d.dep}>{d.dep}</option>)}
          </select>
          <select value={ciudadSel} onChange={(e) => setCiudadSel(e.target.value)} className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} disabled={!depSel}>
            <option value="">Ciudad</option>
            {depObj?.ciudades.map((c) => <option key={c.n} value={c.n}>{c.n}</option>)}
          </select>
        </div>
        <input value={direccion} onChange={(e) => setDireccion(e.target.value)} placeholder="Dirección" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
        <div className="grid grid-cols-3 gap-2">
          <input value={contenido} onChange={(e) => setContenido(e.target.value)} placeholder="Contenido / producto" className="col-span-2 w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
          <input value={cantidad} onChange={(e) => setCantidad(e.target.value)} type="number" placeholder="Cant." className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
        </div>
        <input value={formatMiles(valor)} onChange={(e) => setValor(onlyDigits(e.target.value))} inputMode="numeric" placeholder="Valor a recolectar (contra entrega)" className="w-full px-3 py-2.5 rounded-lg text-sm outline-none" style={inputStyle} />
      </div>

      {/* Al tener el valor a recolectar, se muestran las transportadoras para elegir */}
      {valor && (
        <div className="mt-4">
          <p className="text-xs font-medium mb-2" style={{ color: T.textMuted }}>
            {datosCompletos ? "Elige la transportadora para generar la guía:" : "Completa nombre, teléfono, dirección y ciudad para poder elegir transportadora."}
          </p>
          <div className="grid grid-cols-2 gap-3">
            {["Interrapidísimo", "Coordinadora"].map((c) => (
              <button
                key={c}
                onClick={() => generar(c)}
                disabled={!datosCompletos}
                className="flex flex-col items-center gap-2 p-4 rounded-xl disabled:opacity-40"
                style={{ background: T.panel, border: `1px solid ${T.line}` }}
              >
                <CarrierBadge name={c} size={36} />
                <p className="text-xs font-medium" style={{ color: T.text }}>{c}</p>
                <p className="text-sm font-semibold" style={{ color: T.route }}>{money(codPrice(c, valor))}</p>
              </button>
            ))}
          </div>
        </div>
      )}

      {guideOpen && <NationalGuideModal d={guideOpen} onClose={() => setGuideOpen(null)} />}
    </div>
  );
}


